def transform(grid):
    h, w = len(grid), len(grid[0])
    background = max(
        range(10),
        key=lambda color: sum(cell == color for row in grid for cell in row)
    )
    colors = {cell for row in grid for cell in row if cell not in (0, background)}
    if not colors:
        return [row[:] for row in grid]

    color = next(iter(colors))
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    min_r = min(r for r, c in points)
    min_c = min(c for r, c in points)
    shape = [(r - min_r, c - min_c) for r, c in points]
    shape_h = max(r for r, c in shape) + 1
    shape_w = max(c for r, c in shape) + 1

    out = [row[:] for row in grid]
    for r0 in range(h - shape_h + 1):
        for c0 in range(w - shape_w + 1):
            cells = [(r0 + r, c0 + c) for r, c in shape]
            if all(grid[r][c] == 0 for r, c in cells):
                for r, c in cells:
                    out[r][c] = color
    return out
